import { signal, delegate } from 'kerfjs';
import type { SafeHtml } from 'kerfjs';
import { Toolbar } from '@kerfjs/ui/toolbar';
import { ToolbarText } from '@kerfjs/ui/toolbar-text';
import { ToolbarControlGroup } from '@kerfjs/ui/toolbar-control-group';
import { SegmentedControl } from '@kerfjs/ui/segmented-control';
import '@kerfjs/ui/layout.css';
import './workspace-view.css';

export type WorkspaceView = 'board' | 'list' | 'timeline';
export type ViewAction = { type: 'workspace/view-changed'; value: WorkspaceView };
const choices = [{ value: 'board', label: 'Board' }, { value: 'list', label: 'List' }, { value: 'timeline', label: 'Timeline' }];
export function mountViewChoice(root: HTMLElement, paint: (content: SafeHtml) => void, dispatch: (action: ViewAction) => void, initial: WorkspaceView = 'board') {
  const value = signal<WorkspaceView>(initial);
  const render = () => paint(<div class="workspace-controls kui-layout"><Toolbar label="Workspace controls" leading={<ToolbarText text="Workspace" />} trailing={<ToolbarControlGroup label="Workspace view"><SegmentedControl id="workspace-view" label="View" value={value.value} choices={choices} action="workspace-view-change" appearance="toolbar" size="small" /></ToolbarControlGroup>} /></div>);
  const dispose = delegate(root, 'click', '[data-action="workspace-view-change"]', (_event, button) => {
    const next = button.dataset.segmentValue;
    if (next !== 'board' && next !== 'list' && next !== 'timeline') return;
    if (next === value.value) return;
    value.value = next;
    render();
    dispatch({ type: 'workspace/view-changed', value: next });
  });
  // Native buttons retain Tab, Enter, Space and aria-pressed from SegmentedControl.
  render();
  return { setValue(next: WorkspaceView) { value.value = next; render(); }, dispose };
}
